39.query:
timeseries value = sum(aerospike_namespace_truncating, filter: { in(cluster_name, array($cluster)) and in(service, array($node)) and in(ns, array($namespace)) }, rollup: avg), by: { ns, cluster_name }
| filter coalesce(value[-2], arrayLast(value)) > 0
| fields ns, cluster_name, value = coalesce(value[-2], arrayLast(value))

41.query:
